    """Tuned Best Fit (lo=1, hi=27, penalty=42): the tightest bin wins, but leaving a gap
    strictly between 1 and 27 units costs 42. lo=0, hi=0, penalty=0 is plain Best Fit."""
    r = bins - item                                  # space left in each bin after placing the item
    return -r - 42 * ((r > 1) & (r < 27))

